  let material_match = abs(material_id - row0.x) < 0.5 || abs(material_id - row0.y) < 0.5;
  let phase_match = (row0.z <= 0.5 && row0.w <= 0.5)
    || abs(phase_id - row0.z) < 0.5
    || abs(phase_id - row0.w) < 0.5;
  return material_match && phase_match;
